mapper.update:
update group_buy_stock
set available_stock = available_stock - 1,
    locked_stock = locked_stock + 1
where activity_id = #{activityId}
  and goods_id = #{goodsId}
  and available_stock > 0

update group_buy_stock
set locked_stock = greatest(locked_stock - 1, 0),
    paid_stock = paid_stock + 1
where activity_id = #{activityId}
  and goods_id = #{goodsId}
  and locked_stock > 0

update group_buy_stock
set available_stock = available_stock + 1,
    locked_stock = greatest(locked_stock - 1, 0)
where activity_id = #{activityId}
  and goods_id = #{goodsId}
  and locked_stock > 0

update group_buy_stock
set available_stock = available_stock + 1,
    paid_stock = greatest(paid_stock - 1, 0)
where activity_id = #{activityId}
  and goods_id = #{goodsId}
  and paid_stock > 0
